```python
def count_substrings(s):
    n = len(s)
    suffix_sum = [0] * (n + 1)
    for i in range(n):
        suffix_sum[i + 1] = suffix_sum[i] + (s[i] == '1')

    res = 0
    for i in range(n):
        for j in range(i + 1, n + 1):
            if suffix_sum[j] - suffix_sum[i] == j - i:
                res += 1

    return res
